data.script:
function check(value,message){if(!value)throw Error(message);}
const before=editor.getText();
const plain='café 🐼';
check(Base64.encode('foobar')==='Zm9vYmFy','standard encode');
check(Base64.encode(plain)==='Y2Fmw6kg8J+QvA==','UTF8 encode');
check(Base64.encode('')==='','empty encode');
check(Base64.decode('Zm9vYmFy')==='foobar','standard decode');
check(Base64.decode('Y2Fmw6kg8J+QvA==')===plain,'UTF8 decode');
check(Base64.decode('')==='','empty decode');
check(editor.getText()===before,'editor preserved');
console.log('Base64 encode/decode contracts passed café 🐼');
